package com.realmsoffate.moddingtoolkit.model;
import com.realmsoffate.moddingtoolkit.json.Json;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class DocumentModel {
 private Path path;private Object root;private String savedSnapshot;private final Deque<String> undo=new ArrayDeque<String>(),redo=new ArrayDeque<String>();
 public static DocumentModel open(Path path)throws IOException{String text=new String(Files.readAllBytes(path),StandardCharsets.UTF_8);return new DocumentModel(path,Json.parse(text));}
 public DocumentModel(Path path,Object root){this.path=path;this.root=root;this.savedSnapshot=Json.pretty(root);}public Path path(){return path;}public Object root(){return root;}public void setRoot(Object r){root=r;}public boolean dirty(){return !Json.pretty(root).equals(savedSnapshot);}public void checkpoint(){String s=Json.pretty(root);if(undo.isEmpty()||!undo.peek().equals(s))undo.push(s);redo.clear();}public boolean canUndo(){return !undo.isEmpty();}public boolean canRedo(){return !redo.isEmpty();}public void undo(){if(!canUndo())return;redo.push(Json.pretty(root));root=Json.parse(undo.pop());}public void redo(){if(!canRedo())return;undo.push(Json.pretty(root));root=Json.parse(redo.pop());}public void save()throws IOException{saveAs(path);}
 public void saveAs(Path target)throws IOException{String out=Json.pretty(root)+System.lineSeparator();Json.parse(out);Path abs=target.toAbsolutePath();Path dir=abs.getParent();if(dir==null)throw new IOException("Invalid target path");Files.createDirectories(dir);Path temp=Files.createTempFile(dir,abs.getFileName().toString(),".tmp");try{Files.write(temp,out.getBytes(StandardCharsets.UTF_8),StandardOpenOption.TRUNCATE_EXISTING);Json.parse(new String(Files.readAllBytes(temp),StandardCharsets.UTF_8));if(Files.exists(abs))Files.copy(abs,Paths.get(abs.toString()+".bak"),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.COPY_ATTRIBUTES);try{Files.move(temp,abs,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ex){Files.move(temp,abs,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}path=abs;savedSnapshot=Json.pretty(root);undo.clear();redo.clear();}
}
